if (points.empty()) {
        return Kernel::Plane_3(0, 0, 0, 0);
    }
    if (points.size() == 1) {
        return Kernel::Plane_3(points.front(), Kernel::Vector_3(0, 0, 1));
    }

    // Compute centroid
    Kernel::FT x = 0, y = 0, z = 0;
    for (const auto& p : points) {
        x += p.x();
        y += p.y();
        z += p.z();
    }
    Kernel::FT n = static_cast<Kernel::FT>(points.size());
    Kernel::Point_3 centroid(x / n, y / n, z / n);

    // Compute covariance matrix
    Kernel::FT xx = 0, xy = 0, xz = 0;
    Kernel::FT yy = 0, yz = 0, zz = 0;
    for (const auto& p : points) {
        Kernel::Vector_3 v = p - centroid;
        xx += v.x() * v.x();
        xy += v.x() * v.y();
        xz += v.x() * v.z();
        yy += v.y() * v.y();
        yz += v.y() * v.z();
        zz += v.z() * v.z();
    }

    // Construct symmetric matrix
    Eigen::Matrix<Kernel::FT, 3, 3> cov;
    cov << xx, xy, xz,
           xy, yy, yz,
           xz, yz, zz;

    // Compute smallest eigenvector (normal of the plane)
    Eigen::SelfAdjointEigenSolver<Eigen::Matrix<Kernel::FT, 3, 3>> eigensolver(cov);
    if (eigensolver.info() != Eigen::Success) {
        return Kernel::Plane_3(centroid, Kernel::Vector_3(0, 0, 1));
    }
    Eigen::Matrix<Kernel::FT, 3, 1> normal = eigensolver.eigenvectors().col(0);

    return Kernel::Plane_3(centroid, Kernel::Vector_3(normal(0), normal(1), normal(2)));
// END_CODE

